import { Component } from '@angular/core';
import * as CryptoJS from 'crypto-js';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss'],
})
export class AppComponent {
  title = 'EncryptDecrypt';

  encDecKey: string = '';
  userPlainText: string = '';
  userEncryptedText: string = '';

  encryptedData: string = '';
  decryptedData: string = '';

  clearAll() {
    this.encDecKey = '';
    this.userPlainText = '';
    this.userEncryptedText = '';

    this.encryptedData = '';
    this.decryptedData = '';
  }

  dataEncryptor(plainTextData: any) {
    if (plainTextData && this.encDecKey) {
      let encKey = this.encDecKey;
      const key = CryptoJS.enc.Utf8.parse(encKey);
      const iv = CryptoJS.enc.Utf8.parse(encKey);
      const encyptedData = CryptoJS.AES.encrypt(plainTextData.toString(), key, {
        keySize: 16,
        iv: iv,
        mode: CryptoJS.mode.ECB,
        padding: CryptoJS.pad.Pkcs7,
      });
      this.encryptedData = encyptedData.toString();
      return encyptedData;
    }
    return null;
  }

  dataDecryptor(encryptedData: any) {
    if (encryptedData && this.encDecKey) {
      let encKey = this.encDecKey;
      const key = CryptoJS.enc.Utf8.parse(encKey);
      const iv = CryptoJS.enc.Utf8.parse(encKey);
      const decryptData = CryptoJS.AES.decrypt(encryptedData.toString(), key, {
        keySize: 16,
        iv: iv,
        mode: CryptoJS.mode.ECB,
        padding: CryptoJS.pad.Pkcs7,
      });
      // Convert the decrypted data to string (it will be Base64-encoded)
      const decryptedString = decryptData.toString(CryptoJS.enc.Utf8);
      this.decryptedData = decryptedString;
      return decryptedString;
    }
    return null;
  }
}
<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Encryption/Decryption UI</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
</head>

<body>
  <div class="container">
    <div>
      <label for="form-title" class="form-label mb-4 d-flex justify-content-center">Angular Encryption/Decryption Using
        NPM&nbsp;
        <a href="https://www.npmjs.com/package/crypto-js">crypto-js</a></label>
    </div>
    <div class="key-section mb-4">
      <label for="key" class="form-label">Key</label>
      <input type="text" id="key" class="form-control" placeholder="Enter key here" [(ngModel)]="encDecKey">
    </div>

    <div class="row">
      <div class="col-md-6">
        <label for="plaintext" class="form-label">Plain Text to Encrypt</label>
        <input type="text" id="plaintext" class="form-control" placeholder="Enter plain text"
          [(ngModel)]="userPlainText">
      </div>
      <div class="col-md-6">
        <label for="encryptedtext" class="form-label">Encrypted Text to Decrypt</label>
        <input type="text" id="encryptedtext" class="form-control" placeholder="Enter encrypted text"
          [(ngModel)]="userEncryptedText">
      </div>
    </div>

    <div class="row">
      <div class="col-md-6">
        <div class="row">
          <div class="col-md-6">
            <button type="button" class="btn btn-light" (click)="clearEncryptDataFields()">Clear</button>
          </div>
          <div class="col-md-6">
            <button id="encrypt-btn" class="btn btn-primary" (click)="dataEncryptor(userPlainText)">Encrypt</button>
          </div>
        </div>
      </div>
      <div class="col-md-6">

        <div class="row">
          <div class="col-md-6">
            <button type="button" class="btn btn-light" (click)="clearDecryptDataFields()">Clear</button>
          </div>
          <div class="col-md-6">
            <button id="decrypt-btn" class="btn btn-secondary"
              (click)="dataDecryptor(userEncryptedText)">Decrypt</button>
          </div>
        </div>
      </div>
    </div>

    <div class="row mt-4">
      <div class="col-md-6">
        <div class="label-section">
          <span id="encrypted-label">Encrypted Value: {{encryptedData}}</span>
        </div>
      </div>
      <div class="col-md-6">
        <div class="label-section">
          <span id="decrypted-label">Decrypted Value: {{decryptedData}}</span>
        </div>
      </div>
    </div>

    <div class="d-flex justify-content-end">
      <button type="button" class="btn btn-danger" (click)="clearAll()">Clear All</button>
    </div>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
</body>

</html>
